import collections

def get_neighbors(state, n):
    neighbors = []
    state_list = list(state)
    for i in range(n - 1):
        for j in range(n - 1):
            idx = [i*n + j, i*n + (j + 1), (i + 1)*n + j, (i + 1)*n + (j + 1)]
            vals = [state_list[idx[0]], state_list[idx[1]], state_list[idx[2]], state_list[idx[3]]]
            sum_vals = sum(vals)
            if sum_vals == 3:
                new_state = state_list[:]
                for k in range(4):
                    if vals[k] == 0:
                        new_state[idx[k]] = 1
                neighbors.append(tuple(new_state))
            elif sum_vals == 2:
                new_state = state_list[:]
                for k in range(4):
                    new_state[idx[k]] = 1 - vals[k]
                neighbors.append(tuple(new_state))
    return neighbors

def is_good(state, n):
    target = tuple([1] * (n * n))
    if state == target:
        return True
    visited = {state}
    queue = collections.deque([state])
    while queue:
        curr = queue.popleft()
        if curr == target:
            return True
        for neighbor in get_neighbors(curr, n):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return False

def find_max_bad_k(n):
    max_bad_k = -1
    for i in range(1 << (n * n)):
        state = tuple([(i >> j) & 1 for j in range(n * n)])
        num_ones = sum(state)
        if not is_good(state, n):
            if num_ones > max_bad_k:
                max_bad_k = num_ones
    return max_bad_k + 1

